import os, glob

FAVICON_TAG = """<link rel="icon" type="image/x-icon" href="data:image/x-icon;base64,">
<link rel="apple-touch-icon" href="data:image/png;base64,">"""

# Add to every HTML file in the current folder
for filepath in glob.glob("*.html"):
    with open(filepath, encoding="utf-8") as f:
        content = f.read()
    
    if 'rel="icon"' not in content:
        content = content.replace("</head>", FAVICON_TAG + "\n</head>", 1)
        with open(filepath, "w", encoding="utf-8") as f:
            f.write(content)
        print(f"Added favicon to {filepath}")
    else:
        print(f"Already has favicon: {filepath}")

print("Done!")
